/* This template illustrates how to add custom fields to dialog and how these fields can interact with each other in dialog We will add two fields: customer group id and customer range. Once customer group is changed - customer range clears and lookup is showing customers only from customer group selected before.
STEP 1 - Copy class and make mandatory changes:
This class can be used as template for custom code clases List of things to change for specific report: Mandatory changes : 1. Copy class, rename it to your prefered class name 2. Change LACReportName attribute to specify with which report name this class should work
STEP 2 - Add fields to dialog from code: 1. Create variable that will store dialog field value (see example_CustGroupId, example_CustRange in class declaration) 2. Create method that gets/sets this variable and add attributes for saving, visibility, and sort order(see method parmExample_CustGroupId, parmExample_CustRange)
That is it for adding fields from code into dialog.
STEP 3 - Create functionality for dialog fields interaction: 1. Overwrite method report_dialogPostRun, and use getDialogField() for custom added dialog fields, or getDialogFieldPredefined() - for dialog fields defined in LACReportParameters table
STEP 4 (Optional) - To make it easily accessable from parameters map, you can insert value of your dialog field into parameters map 1. Overwrite method report_dialogGetFrom, and call this.parametersMap().insert(<parameterName>, <parameterOrigValue>, <parameterOrigValueAsString>)
STEP 5 - Build report query and set range just before execution 1. Overwrite queryBuild method and initialize query 2. Overwrite report_runInit and set range for CustTable data source
see more info about methods that can be overwritten in parent class: LACValueSource_CustomCode */ [ DataContractAttribute, SysOperationContractProcessingAttribute(classstr(LACRunQueryUIBuilder)), SysOperationGroupAttribute('Ranges', 'Ranges label', '1'), LACValueSourceAttribute('CustomCode', 'Lasernet custom code'), // "CustomCode" is name shown in value expressions for this class // "Lasernet custom code" is description that is shown in value expressions for this class LACReportName(classStr(LACTutorialCustomCode_WithDialogCode)) ] // Attribute indicating that this class should be used for LACTutorialCustomCode_WithDialog report class LACTutorialCustomCode_WithDialogCode extends LACValueSource_CustomCode { CustGroupId example_CustGroupId; str example_CustRange; int custGroupFormControlId, custRangeFormControlId;
}

Method.Source:
//   ================================================  Step 2 ===========================================================================

/// <summary>
///     This method is used as example how to add Dialog field into report dialog. Method attributes indicates to builder to include it into dialog
/// </summary>
/// <param name = "_custGroupId">The value to set</param>
/// <returns>Example_CustGroupId value</returns>
[   DataMemberAttribute,                          // Save value in class, when switching server-client side, last value
    SysOperationControlVisibilityAttribute(true), // Visible on dialog
    SysOperationDisplayOrderAttribute('1')]       // Ordering inside dialog
public CustGroupId parmExample_CustGroupId(CustGroupId  _custGroupId = example_CustGroupId)
{
    example_CustGroupId  = _custGroupId;
    return example_CustGroupId;
}

/// <summary>
///     This method is used as example how to add Dialog field into report dialog. Method attributes indicates to builder to include it into dialog
/// </summary>
/// <param name = "_custRange">The value to set</param>
/// <returns>Example_CustRange value</returns>
[   DataMemberAttribute,                          // Save value in class, when switching server-client side, last value
    SysOperationControlVisibilityAttribute(true), // Visible on dialog
    SysOperationDisplayOrderAttribute('2'),       // Ordering inside dialog, number 2 indicates that it goes after example_CustGroup
    SysOperationGroupMemberAttribute("Ranges")]   // This will belong to Ranges group defined in class attributes
public str parmExample_CustRange(str  _custRange = example_CustRange)
{
    example_CustRange  = _custRange;
    return example_CustRange;
}

//   ================================================  Step 3 ===========================================================================

/// <summary>
///    This method is called when all dialog form controls are created and dialog is ready to be shown to user
/// </summary>
public void report_dialogPostRun()
{
    DialogField         dialogField;
    FormStringControl   fsc;
    super();
    // Registering modified method for Example_CustGroupId
    dialogField = this.getDialogField(methodStr(LACTutorialCustomCode_WithDialog, parmExample_CustGroupId));
    fsc = dialogField.fieldControl();
    fsc.OnModified += eventhandler(this.example_CustGroupId_onModified); // Register event handler for modified
    fsc.OnValidating += eventhandler(this.example_CustGroupId_onValidating);
    custGroupFormControlId = fsc.id(); // Remember control id because in lookup method we will need to access control for current value

    // Updating Exmple_CustRange field, so it can behave as range field
    dialogField = this.getDialogField(methodStr(LACTutorialCustomCode_WithDialog, parmExample_CustRange));
    // Updating properties on form control
    dialogField.label('Customer range');   // Setting label <- Use label codes in real implementations
    fsc = dialogField.fieldControl();      // Getting FormStringControl object
    fsc.OnLookup += eventhandler(this.example_CustRange_onLookup); // Register event handler for onLookup
    fsc.replaceOnLookup(false);            // Makes it behave like range fields
    fsc.widthMode(FormWidth::ColumnWidth); // Long field so user can see full range
    fsc.displayHeight(1);                  // Single line
    custRangeFormControlId = fsc.id();     // Saving control id for use in Item group modified method

    // NOTE: you can also access controls for predefined parameters
    // Let's say we would like to make language dialog field label bold
    // Language prameter name is hardcoded, but you can access any predefined parameter control by
    // selecting necessary parameter from LACReportParameter table. Please note that LACReportParameters can be generic, or linked to specific caller form name
    LACReportParameter::findCreateLanguageParameter(this.parmReportName(), LACArgsCache::newCache(this.parmReportName())); // Making sure language parameter is created for the report
    if (fsc)
    {
        fsc = this.getParameterControl(LACReportParameter::languageParmName() /* this is fixed name for Language dialog field */);
        fsc.label('Modified Language label'); // <- Use label codes in real implementations
    }
}

/// <summary>
///      This is example of item group dialog field modified method. If field is modified, it clears related item range field
/// </summary>
/// <param name="fsc">
///      Item group dialog field control
/// </param>
public void example_CustGroupId_onModified(FormControl fsc, FormControlEventArgs e)
{
    FormRun           fr = fsc.formRun();
    FormStringControl fscCustRange;
    fscCustRange = fr.control(custRangeFormControlId);  // When item group changed, clearing item Id range field
    fscCustRange.text('');
}

/// <summary>
///      This is example of item group dialog field validating method.
/// </summary>
/// <param name="sender">
///      Item group dialog field control
/// </param>
/// <param name="e">
///      Event args
/// </param>
public void example_CustGroupId_onValidating(FormControl sender, FormControlEventArgs e)
{
    // Reusing built in functionality
    LACReportParameter parameterTmp;
    parameterTmp.IsMandatory    = NoYes::No;
    parameterTmp.AutoValidation = NoYes::Yes;
    parameterTmp.Range          = NoYes::No;
    parameterTmp.ExtTypeName    = extendedTypeStr(CustGroupId);
    this.report_dialogParameterValidate(parameterTmp, sender, e);
    // The same validation is possible manually
    FormStringControl fsc = sender as FormStringControl;
    if (!CustGroup::exist(fsc.text()))
    {
        checkFailed(strFmt('Value %1 not found in related table %2', fsc.text(), tableStr(CustGroup)));
        FormControlCancelEventArgs cancelArgs = e as FormControlCancelEventArgs;
        cancelArgs.cancel(true);
    }
}

/// <summary>
///     Handles lookup for custom itemId field in dialog, by taking current item group value selected in dialog, and filtering out items belonging only to this group
/// </summary>
/// <param name="fsc">
///     Calling control
/// </param>
/// <param name="e">
///     Event handler args
/// </param>
public void example_CustRange_onLookup(FormControl fsc, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs cancelSuper = e as FormControlCancelableSuperEventArgs;
    SysTableLookup       tableLookup = SysTableLookup::newParameters(tableNum(CustTable), fsc, true);
    FormRun              fr = fsc.formRun();
    FormStringControl    fscCustGroup = fr.control(custGroupFormControlId); // Item group dialog field control
    Query                q = new Query();
    QueryBuildDataSource qbds = q.AddDataSource(tableNum(CustTable));

    cancelSuper.CancelSuperCall();

    qbds.addRange(fieldNum(CustTable, CustGroup)).value(fscCustGroup.text()); // Set range on CustTable
    tableLookup.addLookupfield(fieldNum(CustTable, AccountNum), true);
    tableLookup.addLookupMethod(tableMethodStr(CustTable, nameAlias));
    tableLookup.parmQuery(q);
    tableLookup.performFormLookup();
}

//   ================================================  Step 4 Optional ===========================================================================

/// <summary>
///    Get values from dialog
/// </summary>
public void report_dialogGetFrom()
{
    super();
    // If you would like to add your variable into parameters map, use the following. This way you can have easy access to your
    // variable in context methods
    this.parametersMap().insert('example_CustRange', this.parmExample_CustRange(), this.parmExample_CustRange());
}

//   ================================================  Step 5 ===========================================================================

/// <summary>
/// This method serves as example how to build your own query from code. This method builds
/// not only query, but also guidlines for default XML document layout (by adding defaut fields, and Layout options on datasource)
/// </summary>
/// <returns>Query that has been built</returns>
[LACValueSourceRestrictionAttribute('_DO_NOT_SHOW_', '')] // value _DO_NOT_SHOW_ indicates framework, that this method is not 'value' method, and should
// be shown in lookups for value expressions
public Query queryBuild()
{
    Query                queryLocal = new Query();
    // At this example, we will build CustTable query
    // While building query, no parameters and related sources exist
    // specify ranges after report_runInit() is executed
    QueryBuildDataSource qbds;
    // add data source

    qbds = queryLocal.addDataSource(tableNum(CustTable));    // Add datasource
    qbds.name(tableStr(CustTable)); // Data source name will be used as report data source name, so to avoid names like CustTable_1, we set
    // name the same as table name.
    // add fields
    // It's mandatory to add fields with queryBuildAddField() because it serves as source for loading default report elements
    this.queryBuildAddField(qbds, fieldStr(CustTable, AccountNum));
    // or method
    this.queryBuildAddMethod(qbds, tableMethodStr(CustTable, NameAlias));


    /*
    // Adding another datasource
    qbds2 = qbds.addDataSource(tableNum(MyTable2));
    qbds2.name(tableStr(MyTable2)); // Specify meaningfull name for data source
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.fetchMode(QueryFetchMode::One2One);
    qbds2.relations(true);

    // and field
    this.queryBuildAddField(qbds2, fieldStr(MyTable2, NumberOf));

    // !!!! Do not forget this when adding more data sources:
    // Specifying layout property (both tables will be shown in the same xml path depth)
    this.queryBuildAddLayout(query, qbds2, LACQueryDSLayout::SameLevel);
    */
    return queryLocal;
}

/// <summary>
///     Setting query range for selected customers
/// </summary>
[LACValueSourceRestrictionAttribute('_DO_NOT_SHOW_', '')]
public void report_runInit()
{
    QueryBuildDataSource qbds;
    Query                queryLocal;

    super();

    queryLocal = this.getQueryRun().query(); // Retrieving Query from run query service
    qbds = queryLocal.dataSourceTable(tableNum(CustTable));
    SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum)).value(this.parmExample_CustRange()); // Manually setting query range
}

/// <summary>
///   Constructor method, initializing instance of the class
/// </summary>
/// <returns>Class instance</returns>
public static LACTutorialCustomCode_WithDialogCode construct()
{
    return new LACTutorialCustomCode_WithDialogCode();
}

/// <summary>
///   Unpacks class instance. Required method, allowing to cache the custom code for the report execution
/// </summary>
/// <param name = "packedClass">Packed class instance</param>
/// <returns>Class instance</returns>
public static LACTutorialCustomCode_WithDialogCode Create(container packedClass)
{
    LACTutorialCustomCode_WithDialogCode valueSource = LACTutorialCustomCode_WithDialogCode::construct();
    valueSource.unpack(packedClass);
    return valueSource;
}
